function parsePath(raw,base){
 const text=String(raw);let kind,root,rest,parts=[];
 if(/^[A-Za-z]:[\\/]/.test(text)){kind='drive';root=text[0].toUpperCase()+':';rest=text.slice(3).replace(/\\/g,'/')}
 else if(/^(?:\\\\|\/\/)/.test(text)){const a=text.replace(/\\/g,'/').slice(2).split('/');if(!a[0]||!a[1])return null;kind='unc';root='//'+a.shift()+'/'+a.shift();rest=a.join('/')}
 else if(text.startsWith('/')){kind='posix';root='/';rest=text.slice(1)}
 else {if(/^[A-Za-z]:/.test(text)||text.startsWith('\\')||!base)return null;const b=parsePath(base);if(!b)return null;kind=b.kind;root=b.root;parts=b.parts.slice(0,-1);rest=kind==='posix'?text:text.replace(/\\/g,'/')}
 for(const part of rest.split('/')){if(!part||part==='.')continue;if(part==='..'){if(!parts.length)return null;parts.pop()}else parts.push(part)}
 return {kind,root,parts};
}
function formatPath(p){if(!p)return'';if(p.kind==='posix')return'/'+p.parts.join('/');if(p.kind==='drive')return p.root+'\\'+p.parts.join('\\');return p.root.replace(/\//g,'\\')+(p.parts.length?'\\'+p.parts.join('\\'):'')}
function pathKey(p){return p?(p.kind==='posix'?formatPath(p):formatPath(p).toLowerCase()):null}
function samePath(a,b){const x=parsePath(a),y=parsePath(b);return !!(x&&y&&pathKey(x)===pathKey(y))}
function containsPath(scope,target){const a=parsePath(scope),b=parsePath(target);if(!a||!b||a.kind!==b.kind)return false;const key=v=>a.kind==='posix'?v:v.toLowerCase();return key(a.root)===key(b.root)&&a.parts.length<=b.parts.length&&a.parts.every((v,i)=>key(v)===key(b.parts[i]))}
function joinOriginal(root,relative){const p=parsePath(root);return formatPath({...p,parts:[...p.parts,...relative.split('/')]})}
const docs={};
for(const [family,f] of Object.entries(families)){docs[f.spec]={family,kind:'spec',original:joinOriginal(f.root,f.specPath),path:f.specPath};docs[f.api]={family,kind:'api',original:joinOriginal(f.root,f.apiPath),path:f.apiPath}}
function activeFamily(){return families[docs[route().id]?.family||db.family]||families.posix}
function familyOf(target){return families[docs[target.id]?.family]||Object.values(families).find(f=>containsPath(f.root,target.original))||families.posix}
function relativeLink(from,to){const a=parsePath(from),b=parsePath(to);if(!a||!b||a.kind!==b.kind||a.root!==b.root)return to;const parent=a.parts.slice(0,-1);let i=0;while(i<parent.length&&i<b.parts.length&&parent[i]===b.parts[i])i++;return [...parent.slice(i).map(()=> '..'),...b.parts.slice(i)].join('/')}
function existsInFolder(id,path){return !!folders[id]?.files.includes(path)&&!(db.deleted&&id==='r84')}
function folderLocation(id){const f=folders[id];return f?(f.rootId?`${roots[f.rootId]} / ${f.location}`:`${t('직접 선택한 폴더','Directly chosen folder')} · ${f.name}`):''}
function folderPosition(f,muted=false){const cls=muted?'muted path':'path';return f.rootId?`<small class="${cls}">${t('등록 root','Registered root')}: ${esc(roots[f.rootId])}</small><small class="${cls}">${t('root 내부 위치','Location within root')}: ${esc(f.location)}</small>`:`<small class="${cls}">${t('직접 선택한 폴더','Directly chosen folder')}</small>`}
function folderIdentity(id){const f=folders[id];return `<div class="od-field folder-identity"><strong>${esc(f.name)}</strong>${folderPosition(f,true)}</div>`}
function directConnectionFile(b){if(folders[b.folderId].rootId)return'';const d=Object.values(docs).find(d=>containsPath(b.oldRoot,d.original)&&existsInFolder(b.folderId,internalPath(b,d.original)));return d?`<small class="muted path">${t('확인된 내부 파일','Verified file in folder')}: ${esc(internalPath(b,d.original))}</small>`:''}
function gitLabel(f){return f.git==='unknown'?t('Git 확인 불가','Git unknown'):f.git==='none'?t('일반 폴더','Folder'):f.checkout==='worktree'?'Git worktree':'Git clone'}
function gitDetail(f){return f.git==='known'?`${t('저장소','Repository')}: ${f.repo} · ${f.checkout}`:f.git==='unknown'?t('Git 정보는 확인되지 않았지만 내부 파일은 확인할 수 있습니다.','Git identity is unverified; files can still be checked.'):t('Git 없는 일반 폴더','Folder without Git')}

