function normalize(path,base){return formatPath(parsePath(path,base))}
function bindingFor(original,bindings=db.bindings){return [...bindings].filter(b=>folders[b.folderId]&&containsPath(b.oldRoot,original)).sort((a,b)=>parsePath(b.oldRoot).parts.length-parsePath(a.oldRoot).parts.length)[0]}
function internalPath(b,original){if(!containsPath(b.oldRoot,original))return null;return parsePath(original).parts.slice(parsePath(b.oldRoot).parts.length).join('/')}
function resolveTarget(original,bindings=db.bindings){const binding=bindingFor(original,bindings);const path=binding?internalPath(binding,original):null;return {binding,folderId:binding?.folderId,path,exists:!!binding&&existsInFolder(binding.folderId,path)}}
function pathFor(id){const d=docs[id];return d?(resolveTarget(d.original).path||d.path):''}
function repoName(id){const d=docs[id],b=d&&bindingFor(d.original);return b?folders[b.folderId].name:d?folders[families[d.family].folder].name:'—'}
function replaceBinding(bindings,next){return [...bindings.filter(b=>!samePath(b.oldRoot,next.oldRoot)),next]}
function stagedBindings(m){let result=db.bindings.slice();for(const edit of m.edits||[])result=replaceBinding(result,edit);if(m.choice&&m.folder)result=replaceBinding(result,{oldRoot:m.choice.oldRoot,folderId:m.folder});return result}
function overlapsFor(m){return db.bindings.filter(b=>!samePath(b.oldRoot,m.choice.oldRoot)&&(containsPath(b.oldRoot,m.choice.oldRoot)||containsPath(m.choice.oldRoot,b.oldRoot)))}
function scopeChoices(target){const family=familyOf(target),base=parsePath(family.root),full=parsePath(target.original);return Array.from({length:full.parts.length-base.parts.length},(_,i)=>{const oldRoot=formatPath({...full,parts:full.parts.slice(0,base.parts.length+i)});return{oldRoot,path:full.parts.slice(base.parts.length+i).join('/')}})}

