function renderDocList(){const r=route();let list=[['n08','08_overview.md'],['n12','12_search_plan.md'],['n18','18_writing.md']];if($('#doc-sort')?.value==='title')list.sort((a,b)=>docTitle(a[0]).localeCompare(docTitle(b[0]),db.lang));if(session.onlyPlan)list=list.filter(([id])=>id==='n12');list=list.filter(([id,file])=>!searchText||(docTitle(id)+' '+file).toLowerCase().includes(searchText.toLowerCase()));$('#doc-list').innerHTML=list.length?list.map(([id,file])=>`<a class="doc-nav${r.type==='source'&&r.id===id?' active':''}" href="${sourceRoute(id)}" ${r.type==='source'&&r.id===id?'aria-current="page"':''}>${icon('file')}<span class="od-field od-fill"><strong>${docTitle(id)}</strong><small>${file}</small></span></a>`).join(''):`<div class="empty-state"><p>${t('일치하는 문서가 없습니다.','No matching documents.')}</p>${button('clear-search',t('검색 지우기','Clear search'),'ghost')}</div>`}
