function toc(items){return`<aside class="toc" aria-label="${t('이 문서에서','On this page')}"><p class="toc-title">${t('이 문서에서','On this page')}</p>${items.map(([id,label])=>`<a href="#${id}" data-section="${id}">${label}</a>`).join('')}</aside>`}
function sourceBody(id){const f=activeFamily();if(id!=='n12')return`<div class="doc-kicker">${icon('file')}${t('프로젝트 문서','Project document')}</div><h1 tabindex="-1" class="doc-title">${docTitle(id)}</h1><div class="doc-meta"><span>Product Notes</span><span class="path">docs/${id==='n08'?'08_overview.md':'18_writing.md'}</span></div><article class="ak-markdown"><h2>${id==='n08'?t('문서로 함께 일하기','Working with documents'):t('읽기 쉬운 문서','Readable documents')}</h2><p>${id==='n08'?t('검색 경험을 개선하기 위한 계획과 설계, API 계약을 함께 정리합니다.','Plans, interface design, and API contracts for improving the search experience.'):t('문서의 목적을 먼저 쓰고, 관련된 설계와 계약은 링크로 연결합니다.','Start with the purpose of the document and link to related designs and contracts.')}</p><p><a href="${sourceRoute()}">${docTitle('n12')}</a></p></article>`;
return`<div class="doc-kicker">${icon('file')}${t('프로젝트 문서','Project document')}${badge(t('계획','Plan'))}</div><h1 tabindex="-1" class="doc-title">${docTitle('n12')}</h1><div class="doc-meta"><span class="od-row">${icon('folder')}Product Notes</span><span class="path">docs/12_search_plan.md</span></div><p class="doc-intro">${t('찾고 싶은 문서에 더 빠르게 닿을 수 있도록, 검색 흐름과 결과 화면을 정리합니다.','A clearer search flow and results page to help people find the document they need.')}</p><hr class="rule"><article class="ak-markdown"><h2 id="goal">${t('개선 목표','Goals')}</h2><p>${t('검색어를 입력한 뒤 결과를 고르고, 필요한 문서까지 자연스럽게 이어지는 경험을 만듭니다.','Make it easy to move from a query to a result, then to the right document.')}</p><ul><li>${t('제목과 본문을 함께 검색합니다.','Search titles and document contents together.')}</li><li>${t('검색어와 일치하는 부분을 결과에서 바로 확인합니다.','See matching text directly in the results.')}</li><li>${t('문서를 읽고 돌아와도 검색 조건을 유지합니다.','Keep search conditions when returning from a document.')}</li></ul><h2 id="design">${t('화면 설계','Interface design')}</h2><p>${t('입력창과 결과 목록의 동작은 아래 설계 문서에서 확인합니다.','See the design document for search input and results behavior.')}</p><a class="related-link" id="primary-link" href="${linkedRoute(f.spec)}" data-link="${esc(docs[f.spec].original)}"><span class="related-icon">${icon('file')}</span><span class="od-field od-fill"><strong>${docTitle('x21')}</strong><small>${t('검색창 · 결과 목록 · 빈 결과','Search input · Results · Empty states')}</small></span>${icon('arrow')}</a><details class="small muted"><summary>${t('링크 경로','Link path')}</summary><p class="path">${esc(docs[f.spec].original)}</p></details><h2 id="decisions">${t('함께 확인할 내용','Review points')}</h2><ul><li>${t('검색 결과에서 제목과 본문을 구분할 수 있는가?','Are titles and body matches easy to distinguish?')}</li><li>${t('결과가 없을 때 다음 행동이 분명한가?','Is the next step clear when there are no results?')}</li></ul></article><footer class="doc-footer">${icon('file')}<span>Product Notes <span aria-hidden="true">/</span> ${t('문서 12','Document 12')}</span></footer>`;
}
function linkedBody(r){const known=docs[r.id],f=known?families[known.family]:activeFamily(),actual=known?resolveTarget(known.original):{},b=actual.binding;let err='';if(!known)err='unknown';else if(!b)err='disconnected';else if(!db.permission)err='permission';else if(db.deleted&&b.folderId==='r84')err='deleted';else if(!actual.exists)err='missing';
const head=`<div class="linked-top">${button('source',t('출발 문서로 돌아가기','Back to source document'),'ghost','back')}${badge(t('읽기 전용','Read only'),false,'lock')}</div><div class="doc-kicker">${icon('link')}${t('연결된 문서','Linked document')}</div><h1 tabindex="-1" class="doc-title">${docTitle(r.id)}</h1><div class="read-context"><div class="od-row-top">${icon('folder')}<div class="od-fill">${known?folderIdentity(b?.folderId||f.folder):`<strong>${t('요청한 문서','Requested document')}</strong>`}</div>${badge(b?t('연결 폴더','Connected folder'):t('연결 필요','Connection needed'))}</div><div class="context-path path">${known?esc(pathFor(r.id)):t('문서 ID','Document ID')+': '+esc(r.id)}</div>${known?`<details class="small muted"><summary>${t('원본 전체 주소','Full original address')}</summary><p class="path">${esc(known.original)}</p></details>`:''}</div>`;
if(err){const content={permission:[t('폴더 접근을 다시 허용해 주세요','Allow folder access again'),t('표시된 폴더에 대한 접근이 만료되었습니다. 접근을 허용하거나 다른 폴더를 연결하세요.','Access to the displayed folder has expired. Allow access or connect another folder.')],disconnected:[t('문서의 연결이 필요합니다','This document needs a connection'),t('이 주소에 연결된 폴더가 없습니다. 폴더를 연결하면 요청한 문서를 이어서 읽을 수 있습니다.','No folder is connected for this address. Connect a folder to continue reading the requested document.')],deleted:[t('파일을 찾을 수 없습니다','File not found'),t('연결된 폴더에서 요청한 파일이 사라졌습니다. 다른 폴더를 연결하거나 출발 문서로 돌아가세요.','The requested file is no longer in the connected folder. Connect another folder or return to the source document.')],missing:[t('연결 범위에서 파일을 찾지 못했습니다','File not found in this connection'),t('요청한 경로를 포함하는 다른 폴더를 선택해 주세요.','Choose a folder containing the requested path.')],unknown:[t('문서 ID를 찾을 수 없습니다','Document ID not found'),t('이 주소의 문서 정보를 찾지 못했습니다. 출발 문서에서 링크를 다시 열어 주세요.','No document matches this address. Open the link again from the source document.')]}[err];return head+`<section class="request-error">${icon(err==='permission'?'lock':'file')}<h2>${content[0]}</h2><p>${content[1]}</p>${known?`<details class="small muted"><summary>${t('요청 경로 확인','View requested path')}</summary><p class="path">${esc(known.original)}</p></details>`:''}<div class="od-cluster">${err==='permission'?button('grant',t('접근 허용','Allow access'),'primary','lock'):''}${known?button('reconnect',err==='permission'?t('다른 폴더','Another folder'):t('다시 연결','Reconnect'),err==='permission'?'outline':'primary','folder'):''}${button('source',t('출발 문서로','Source document'),'outline','back')}</div></section>`}
let body=known.kind==='spec'?`<p class="doc-intro">${t('검색은 한 번의 입력에서 시작해, 원하는 문서를 읽는 순간까지 이어집니다.','Search starts with a query and ends with reading the right document.')}</p><hr class="rule"><h2 id="input">${t('검색 입력','Search input')}</h2><p>${t('상단 검색창에서 제목과 본문을 함께 검색합니다. 입력한 검색어는 문서를 열고 돌아온 뒤에도 유지합니다.','Search titles and contents from the top search field. Keep the query when returning from an opened document.')}</p><h2 id="results">${t('결과 목록','Results list')}</h2><ul><li>${t('제목, 문서 경로, 일치하는 본문을 순서대로 표시합니다.','Show the title, document path, and matching excerpt in that order.')}</li><li>${t('선택한 결과는 읽기 화면으로 이동합니다.','Open a selected result in the document reader.')}</li><li>${t('검색 결과가 없으면 검색어를 바꿀 수 있도록 안내합니다.','When there are no results, suggest changing the query.')}</li></ul><h2 id="contract">${t('관련 API 계약','Related API contract')}</h2><p>${t('요청과 응답 형식은 검색 API 계약을 따릅니다.','Use the search API contract for request and response formats.')}</p><div class="related-link"><span class="related-icon">${icon('file')}</span><div class="od-field od-fill"><strong>${linkedAnchor(f.api,'absolute')}</strong><small class="path">${esc(docs[f.api].original)}</small></div>${icon('arrow')}</div><p>${t('같은 문서의 상대 링크','Relative link to the same document')}: ${linkedAnchor(f.api,'relative')} <code>${esc(relativeLink(known.original,docs[f.api].original))}</code></p><h2 id="files">${t('참고 파일','Reference file')}</h2><p><a href="#" data-link="${esc(joinOriginal(f.root,'src/search.ts'))}">${icon('download')} search.ts ${t('다운로드','download')}</a> <span class="small muted">TypeScript</span></p>`:`<p class="doc-intro">${t('검색 요청과 결과 목록이 주고받는 데이터 형식을 정의합니다.','The request and response format shared by search input and the results list.')}</p><hr class="rule"><h2 id="request">${t('요청','Request')}</h2><p><code>GET /search?q=keyword</code></p><table class="mini-table"><thead><tr><th>${t('필드','Field')}</th><th>${t('설명','Description')}</th></tr></thead><tbody><tr><td><code>q</code></td><td>${t('검색어 · 앞뒤 공백 제외','Search query, trimmed')}</td></tr><tr><td><code>limit</code></td><td>${t('한 번에 가져올 결과 수','Maximum number of results')}</td></tr></tbody></table><h2 id="response">${t('응답','Response')}</h2><pre>{
  "items": [
    { "id": "s01", "title": "${docTitle('x21')}",
      "path": "${esc(f.specPath)}" }
  ]
}</pre><h2 id="empty">${t('빈 결과','Empty results')}</h2><p>${t('일치하는 문서가 없으면 빈 목록을 반환합니다. 입력한 검색어는 그대로 유지합니다.','Return an empty list when no documents match. Keep the original search query.')}</p><p>${t('관련 설계','Related design')}: <a href="${linkedRoute(f.spec)}" data-link="${esc(relativeLink(known.original,docs[f.spec].original))}">${docTitle('x21')}</a></p>`;
return head+`<article class="ak-markdown">${body}</article><footer class="doc-footer">${icon('lock')}<span>${t('이 문서는 읽기 전용으로 열렸습니다.','This document is open in read-only mode.')}</span></footer>`;
}
function renderPage(focus=false){const r=route();currentRoute=location.hash||sourceRoute();document.documentElement.lang=db.lang;$('.skip-link').textContent=t('본문으로 건너뛰기','Skip to content');$('#sidebar').setAttribute('aria-label',t('프로젝트 문서','Project documents'));document.documentElement.classList.toggle('dark',db.theme==='dark');document.title=`${docTitle(r.id)} · Alpha Kanban`;renderHeader();renderSidebar();const linked=r.type!=='source';const readable=linked?!!(docs[r.id]&&resolveTarget(docs[r.id].original).exists&&db.permission):r.id==='n12';$('#main').innerHTML=`<div class="location-bar">${button('sidebar',t('문서','Documents'),'ghost mobile-docs','menu','aria-controls="sidebar" aria-expanded="'+sidebarOpen+'"')}<div class="breadcrumb"><span>Product Notes</span>${icon('chevron')}<span>${linked?t('연결된 문서','Linked document'):t('문서','Documents')}</span>${!linked?`${icon('chevron')}<span class="path">${r.id==='n12'?'12_search_plan.md':r.id==='n08'?'08_overview.md':'18_writing.md'}</span>`:''}</div>${linked?`<div class="location-actions">${button('connections',t('연결 관리','Connections'),'ghost sm','link')}</div>`:''}</div><div class="doc-layout"><div class="document">${linked?linkedBody(r):sourceBody(r.id)}</div>${readable?toc(linked?(docs[r.id]?.kind==='api'?[['request',t('요청','Request')],['response',t('응답','Response')],['empty',t('빈 결과','Empty results')]]:[['input',t('검색 입력','Search input')],['results',t('결과 목록','Results list')],['contract',t('API 계약','API contract')],['files',t('참고 파일','Reference file')]]):[['goal',t('개선 목표','Goals')],['design',t('화면 설계','Interface design')],['decisions',t('함께 확인할 내용','Review points')]]):''}</div>`;
renderReview();if(focus){$('.doc-title')?.focus({preventScroll:true});requestAnimationFrame(()=>window.scrollTo(0,session.scroll[currentRoute]||0))}}
function openLink(raw,anchor){const f=activeFamily(),base=docs[route().id]?.original||joinOriginal(f.root,'docs/12_search_plan.md');const p=parsePath(raw,base);if(!p){notify('이 링크의 경로 형식을 확인해 주세요.','Check the path format of this link.');return}const original=formatPath(p),id=Object.keys(docs).find(k=>samePath(docs[k].original,original));const actual=resolveTarget(original);
 if(actual.binding){if(id){navigate(linkedRoute(id));return}if(actual.exists&&db.permission&&original.endsWith('search.ts')){download();return}}
 openConnect({original,id:id||'file',title:id?docTitle(id):'search.ts'},anchor)
}

function download(){const a=document.createElement('a');a.href=URL.createObjectURL(new Blob(['// Fictional search reference\nexport function search(query: string) {\n  return { query: query.trim(), items: [] };\n}\n'],{type:'text/plain;charset=utf-8'}));a.download='search.ts';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);notify('search.ts를 다운로드했습니다.','Downloaded search.ts.')}
function closeDialog(restore=true){if(restore&&modal?.parent){modal=modal.parent;renderConnect();requestAnimationFrame(()=>$('#dialog [data-action="edit-effective"]')?.focus());return}if(restore&&modal?.fromManagement){modal={type:'connections'};renderInfo();return}clearTimeout(scanTimer);const d=$('#dialog');if(d.open)d.close();modal=null;$('#dialog').innerHTML='';if(restore&&originFocus){const target=originFocus.isConnected?originFocus:(originFocus.id?document.getElementById(originFocus.id):null);target?.focus({preventScroll:true})}originFocus=null}
function showModal(content,focusSelector){const d=$('#dialog');d.innerHTML=content;if($('#dialog-description',d))d.setAttribute('aria-describedby','dialog-description');else d.removeAttribute('aria-describedby');if(!d.open)d.showModal();requestAnimationFrame(()=>{if(d.open)$(focusSelector||'[data-initial]',d)?.focus({preventScroll:true})})}
function shell(title,desc,body,footer){return`<header class="dialog-header"><div class="od-fill"><h2 id="dialog-title" tabindex="-1" data-initial>${title}</h2>${desc?`<p id="dialog-description">${desc}</p>`:''}</div>${button('cancel',`<span class="sr-only">${t('닫기','Close')}</span>`,'ghost icon','close')}</header><div class="dialog-body">${body}</div><footer class="dialog-footer">${footer}</footer>`}
function targetMarkup(){return`<div class="target-file">${icon(modal.target.id==='file'?'download':'file')}<div class="od-fill"><strong>${esc(modal.target.title)}</strong><details><summary>${t('원본 링크 확인','View original link')}</summary><p class="path">${esc(modal.target.original)}</p></details></div></div>`}
function suggested(folderId){const options=modal.lockedRoot?[{oldRoot:modal.lockedRoot,path:internalPath({oldRoot:modal.lockedRoot},modal.target.original)}]:scopeChoices(modal.target).filter((o,i)=>i===(folders[folderId].level||0)||(mode==='mappings'&&folderId==='r84'));return options.filter(o=>existsInFolder(folderId,o.path))}
function selectFolder(id){modal.folder=id;modal.error='';modal.ack=false;modal.options=suggested(id);if(!modal.options.length){modal.choice=modal.lockedRoot?{oldRoot:modal.lockedRoot,path:internalPath({oldRoot:modal.lockedRoot},modal.target.original)}:scopeChoices(modal.target)[folders[id].level||0]||scopeChoices(modal.target)[0];modal.step='missing'}else if(modal.options.length>1){modal.choice=null;modal.step='mapping'}else{modal.choice=modal.options[0];modal.step='confirm'}renderConnect()}
function searchProfile(){
 const f=activeFamily();
 if(f!==families.posix)return{roots:[folders[f.folder].rootId],ids:[f.folder],outcome:f===families.unc?'git-unknown':'complete'};
 const profiles={
  'no-roots':{roots:[],ids:[],outcome:'no-roots'},'no-repos':{roots:['wa','wb'],ids:[],outcome:'empty'},
  'multi-root':{roots:['wa','wb'],ids:['r91','r92','r93'],outcome:'complete'},
  'limit-depth':{roots:['wa','wb'],ids:['r91'],outcome:'limit-depth'},'limit-time':{roots:['wa','wb'],ids:['r91','r92'],outcome:'limit-time'},
  'git-unknown':{roots:['wb'],ids:['g01'],outcome:'git-unknown'},multiple:{roots:['ws'],ids:['r84','r85'],outcome:'complete'},
  partial:{roots:['ws'],ids:['r84'],outcome:'partial'}
 };
 return profiles[mode]||{roots:['ws'],ids:db.deleted?['r84','r85']:['r84'],outcome:'complete'}
}
function searchCopy(state){return ({
 scanning:[t('repo 검색 중…','Searching for repos…'),t('지금까지 찾은 폴더를 먼저 선택할 수 있습니다.','You can select folders already found.')],
 complete:[t('검색 완료','Search complete'),''],
 'no-roots':[t('검색할 root 없음','No searchable roots'),t('검색할 수 있는 등록 root가 없습니다. 폴더를 직접 선택해 계속하세요.','There are no searchable registered roots. Choose a folder directly to continue.')],
 empty:[t('repo를 찾지 못함','No repos found'),t('검색한 root에서 repo를 찾지 못했습니다. 일반 폴더도 직접 선택할 수 있습니다.','No repos were found in these roots. You can still choose an ordinary folder.')],
 stopped:[t('검색 중단됨','Search stopped'),t('중단 전 발견한 폴더만 표시합니다. 나머지 위치는 검색하지 않았습니다.','Only folders found before stopping are shown. Other locations were not searched.')],
 partial:[t('일부 검색 실패','Partial search failure'),t('archive 폴더에 접근하지 못했습니다. 이미 찾은 후보는 선택할 수 있습니다.','Could not access archive. Already discovered candidates remain available.')],
 'limit-depth':[t('탐색 깊이 제한','Search depth reached'),t('깊은 하위 폴더는 검색하지 못했습니다. 찾은 후보를 선택하거나 폴더를 직접 선택하세요.','Deeper folders were not searched. Select a found folder or choose one directly.')],
 'limit-time':[t('탐색 시간 제한','Search time reached'),t('시간 제한으로 일부 위치만 검색했습니다. 이 목록이 전체 결과는 아닙니다.','Only some locations were searched before the time limit. This list is incomplete.')],
 'git-unknown':[t('Git 정보 확인 불가','Git identity unavailable'),t('gitdir이 허용된 범위 밖이거나 지원하지 않는 구성입니다. 저장소 동일성은 확인하지 않고 폴더 안의 파일만 확인합니다.','The gitdir is outside the allowed scope or uses an unsupported configuration. Repository identity is unverified; files inside the folder can still be checked.')]
 })[state]}
function beginScan(){clearTimeout(scanTimer);const m=modal;if(!m?.profile.roots.length){m.scanState='no-roots';return}m.scanState='scanning';scanTimer=setTimeout(()=>{if(modal===m){m.scanState=m.profile.outcome;if(m.step==='discover')renderConnect(false)}},mode==='scan'?12000:1400)}
function openConnect(target,anchor){originFocus=anchor||document.activeElement;modal={type:'connect',target,step:'discover',folder:null,choice:null,version:db.version,error:'',query:'',rootFilter:'all',profile:searchProfile(),ack:false,edits:[]};beginScan();renderConnect()}
